    /**
     * assign Account on FeeCharge
     * @param		command AssignAccountToFeeChargeCommand	
     * @exception	ProcessingException
     */     
	public void assignAccount( AssignAccountToFeeChargeCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getFeeChargeId() );
		
		AccountService childDelegate 	= AccountService.getAccountInstance();
		FeeChargeService parentDelegate = FeeChargeService.getFeeChargeInstance();			
		UUID childId = command.getAssignment().getAccountId();
		Account child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	FeeChargeValidator.getInstance().validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Account using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

